import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.CB_NIqHd.js";const b=JSON.parse('{"title":"Why Accessibility Matters","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/A11y/Why_a11y_matters.md","filePath":"senior_growth/A11y/Why_a11y_matters.md"}'),s={name:"senior_growth/A11y/Why_a11y_matters.md"};function o(n,e,l,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="why-accessibility-matters" tabindex="-1">Why Accessibility Matters <a class="header-anchor" href="#why-accessibility-matters" aria-label="Permalink to “Why Accessibility Matters”">​</a></h1><p><strong>Accessibility (a11y)</strong> aims to remove barriers so people, including those with disabilities, can <strong>perceive, understand, navigate, and interact</strong> with a website or application. The term “a11y” comes from <strong>“accessibility”</strong>, with 11 representing the letters between “a” and “y”.</p><hr><h2 id="_1️⃣-importance-of-accessibility" tabindex="-1">1️⃣ Importance of Accessibility <a class="header-anchor" href="#_1️⃣-importance-of-accessibility" aria-label="Permalink to “1️⃣ Importance of Accessibility”">​</a></h2><h3 id="_1-1-legal-compliance-reasons" tabindex="-1">1.1 Legal &amp; Compliance Reasons <a class="header-anchor" href="#_1-1-legal-compliance-reasons" aria-label="Permalink to “1.1 Legal &amp; Compliance Reasons”">​</a></h3><ul><li>Technical accessibility criteria, product contracts and applicable legal obligations are related but distinct.</li><li>This study note does not determine jurisdiction, coverage, required standard/version or legal compliance; the product needs an assessment of its actual scope.</li></ul><h3 id="_1-2-inclusive-user-experience" tabindex="-1">1.2 Inclusive User Experience <a class="header-anchor" href="#_1-2-inclusive-user-experience" aria-label="Permalink to “1.2 Inclusive User Experience”">​</a></h3><ul><li>People have varied visual, auditory, cognitive and motor access needs; an undated prevalence statistic is not needed to justify removing a concrete barrier.</li><li>Accessible task design reduces exclusion; actual usability and remaining barriers require testing with the relevant people and technologies.</li></ul><h3 id="_1-3-seo-discoverability" tabindex="-1">1.3 SEO &amp; Discoverability <a class="header-anchor" href="#_1-3-seo-discoverability" aria-label="Permalink to “1.3 SEO &amp; Discoverability”">​</a></h3><ul><li>Clear content structure and meaningful alternatives help people understand and navigate content.</li><li>Neither ARIA attributes nor a tool score guarantee a search rank or useful assistive-technology behavior.</li></ul><h3 id="_1-4-usability-for-everyone" tabindex="-1">1.4 Usability for Everyone <a class="header-anchor" href="#_1-4-usability-for-everyone" aria-label="Permalink to “1.4 Usability for Everyone”">​</a></h3><ul><li>Accessibility features like <strong>keyboard navigation, clear color contrast, and readable fonts</strong> benefit <strong>all users</strong>, not only those with disabilities.</li><li>Example: captions on videos help in <strong>noisy environments</strong>, high contrast helps in <strong>bright sunlight</strong>.</li></ul><h3 id="_1-5-ethical-brand-reputation" tabindex="-1">1.5 Ethical &amp; Brand Reputation <a class="header-anchor" href="#_1-5-ethical-brand-reputation" aria-label="Permalink to “1.5 Ethical &amp; Brand Reputation”">​</a></h3><ul><li>Shows commitment to <strong>social responsibility</strong> and <strong>inclusive design</strong>.</li><li>Builds <strong>trust</strong> and a <strong>positive reputation</strong> among users and partners.</li></ul><hr><h2 id="_2️⃣-common-accessibility-considerations" tabindex="-1">2️⃣ Common Accessibility Considerations <a class="header-anchor" href="#_2️⃣-common-accessibility-considerations" aria-label="Permalink to “2️⃣ Common Accessibility Considerations”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Example Practices</th></tr></thead><tbody><tr><td>Visual</td><td>Sufficient color contrast, resizable text, high DPI support</td></tr><tr><td>Auditory</td><td>Captions and transcripts for videos/audio</td></tr><tr><td>Motor / Interaction</td><td>Keyboard navigability, larger clickable areas</td></tr><tr><td>Cognitive</td><td>Clear language, predictable layouts, consistent UI</td></tr><tr><td>ARIA &amp; Semantic HTML</td><td>Correct roles, labels, and landmarks</td></tr><tr><td>Forms</td><td>Proper labels, error messages, tab order</td></tr></tbody></table><hr><h2 id="_3️⃣-tools-to-check-a11y" tabindex="-1">3️⃣ Tools to Check a11y <a class="header-anchor" href="#_3️⃣-tools-to-check-a11y" aria-label="Permalink to “3️⃣ Tools to Check a11y”">​</a></h2><ul><li><strong>Lighthouse (Chrome DevTools)</strong></li><li><strong>axe DevTools</strong></li><li><strong>WAVE Web Accessibility Evaluation Tool</strong></li><li><strong>Screen readers:</strong> NVDA, VoiceOver</li></ul><hr><h2 id="_4️⃣-best-practices" tabindex="-1">4️⃣ Best Practices <a class="header-anchor" href="#_4️⃣-best-practices" aria-label="Permalink to “4️⃣ Best Practices”">​</a></h2><ol><li>Use <strong>semantic HTML</strong> (headings, lists, buttons, forms).</li><li>Ensure <strong>keyboard-only accessibility</strong>.</li><li>Provide <strong>text alternatives</strong> for non-text content.</li><li>Check applicable contrast criteria: normal text generally4.5:1, qualifying large text3:1, and required nontext indicators3:1, with the defined exceptions.</li><li>Use <strong>ARIA attributes</strong> only when necessary.</li><li>Test with <strong>real assistive technologies</strong>.</li></ol><hr><h3 id="✅-summary" tabindex="-1">✅ Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “✅ Summary”">​</a></h3><ul><li>Accessibility is about <strong>inclusion, legal compliance, and usability</strong>.</li><li>Benefits everyone: users with disabilities, SEO, and general usability.</li><li>Ignoring a11y can lead to <strong>legal risk, lost users, and poor reputation</strong>.</li></ul><blockquote><p>💡 Senior Tip:<br> Treat accessibility as <strong>part of the design and development process</strong>, not as an afterthought. Integrate it early and retain task-based evidence; a guideline or one passing tool run does not establish universal usability.</p></blockquote><h2 id="turn-the-rationale-into-observable-task-outcomes" tabindex="-1">Turn the rationale into observable task outcomes <a class="header-anchor" href="#turn-the-rationale-into-observable-task-outcomes" aria-label="Permalink to “Turn the rationale into observable task outcomes”">​</a></h2><p>A useful first task is finding a note and recovering when the enhanced search fails. The <a href="./../Other/Cross_Browser_Progressive_Enhancement.html">HTML-first search fixture</a> supplies a configured browser test path; the <a href="./../React/React_testing.html">React component lesson</a> supplies executable pending/error/retry behavior. Neither is claimed as a measured accessibility project outcome. Follow the <a href="./Can_we_test,_measure_a11y_somehow.html">audit and retest contract</a> for actual keyboard, reader, reflow and contrast evidence.</p><p><strong>Acceptance:</strong> choose one important task and access need; describe the starting state, input method, expected outcome and failure/recovery path. Record a real observed barrier, a scoped correction and retest under the same conditions. Keep automated DOM behavior, native browser observations and user/reader evidence separate. A personal statement such as “we test accessibility” requires retained project evidence; learner practice remains required.</p><p>Authoritative guidance checked 2026-10-22: <a href="https://www.w3.org/WAI/test-evaluate/" target="_blank" rel="noreferrer">WAI evaluation overview</a>, <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noreferrer">WCAG2.2 technical criteria and conformance</a>.</p>',31)])])}const g=t(s,[["render",o]]);export{b as __pageData,g as default};
